import json
import os
import time

from app.config import CACHE_PATH, CACHE_TTL


def _read_cache():
    try:
        with open(CACHE_PATH, "r") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _write_cache(data):
    os.makedirs(os.path.dirname(CACHE_PATH), exist_ok=True)
    with open(CACHE_PATH, "w") as f:
        json.dump(data, f)


def get_or_load(key, loader, now=None):
    if now is None:
        now = time.time()
    cache = _read_cache()
    entry = cache.get(key)
    if entry is not None and (now - entry["stored_at"]) < CACHE_TTL:
        return entry["value"]
    value = loader()
    cache[key] = {"stored_at": now, "value": value}
    try:
        _write_cache(cache)
    except OSError:
        pass
    return value"}

